const response = $input.first().json;
const issues = response.issues || [];
if (issues.length === 0) {
  return [];
}
return issues.map(issue => ({ json: issue }));

const item = $input.first().json;
const fields = item.fields || {};

function extractTextFromAdf(adf) {
  if (!adf || typeof adf !== 'object') return '';
  const texts = [];
  function extract(node) {
    if (typeof node === 'string') { texts.push(node); return; }
    if (node && typeof node === 'object') {
      if (node.text) texts.push(node.text);
      if (Array.isArray(node.content)) node.content.forEach(extract);
    }
    if (Array.isArray(node)) node.forEach(extract);
  }
  extract(adf);
  return texts.join(' ');
}

const description = extractTextFromAdf(fields.description);
const summary = fields.summary || '';
const key = item.key || '';
const issueType = (fields.issuetype && fields.issuetype.name) ? fields.issuetype.name : '';

let shouldProcess = true;
let skipReason = '';

if (!description || description.trim().length === 0) {
  shouldProcess = false;
  skipReason = 'Empty description';
} else if (description.toLowerCase().includes('acceptance criteria')) {
  shouldProcess = false;
  skipReason = 'Already has acceptance criteria';
}

return [{
  json: {
    shouldProcess,
    skipReason,
    ticketKey: key,
    summary,
    description,
    descriptionAdf: fields.description,
    issueType
  }
}];

const ticket = $input.first().json;
const config = $('Set Config').first().json;

const systemPrompt = 'You are an expert at analyzing software development tickets and extracting their core subject matter.\n\nYour task is to read a Jira ticket\'s summary and description, then extract the key topics, entities, domain concepts, and business terms.\n\nGUIDELINES:\n- Identify the primary domain area (e.g., payments, authentication, reporting)\n- Extract named entities such as systems, services, APIs, or integrations\n- Capture business terms and domain-specific language\n- Note any technical concepts, frameworks, or tools mentioned\n- Return a consolidated natural-language summary that provides rich context about what this ticket is about — NOT a list of keywords\n\nUse the submit_extracted_topics tool to provide your response.';

const userMessage = 'TICKET SUMMARY: ' + ticket.summary + '\n\nTICKET DESCRIPTION:\n' + ticket.description + '\n\nAnalyze this ticket and extract the key topics using the submit_extracted_topics tool.';

const requestBody = {
  model: config.aiModel,
  max_tokens: parseInt(config.aiMaxTokens) || 1024,
  system: systemPrompt,
  tools: [{
    name: 'submit_extracted_topics',
    description: 'Submit the extracted topics, entities, and domain concepts from a Jira ticket',
    input_schema: {
      type: 'object',
      properties: {
        topics: {
          type: 'string',
          description: 'A consolidated natural-language summary of the key topics, entities, domain concepts, and business terms found in the ticket.'
        }
      },
      required: ['topics']
    }
  }],
  tool_choice: { type: 'tool', name: 'submit_extracted_topics' },
  messages: [{ role: 'user', content: userMessage }]
};

return [{ json: { requestBody } }];

const ticket = $('Validate Ticket').first().json;
const config = $('Set Config').first().json;
const response = $input.first().json;

let topics = '';
try {
  const content = response.content || [];
  for (const block of content) {
    if (block.type === 'tool_use' && block.name === 'submit_extracted_topics') {
      topics = (block.input && block.input.topics) ? block.input.topics : '';
    }
  }
} catch (e) {
  topics = ticket.description;
}

const projectCtx = config.barleyProjectName ? ('Project: ' + config.barleyProjectName + '\n') : '';
const barleyPrompt = projectCtx + 'Feature: ' + ticket.summary + '\nTopics: ' + topics + '\n\nProvide context for writing acceptance criteria. Respond in markdown with these sections:\n## User Personas\n## Relevant Workflows\n## Acceptance Criteria Patterns\n## Domain Context';

const barleyRequestBody = {
  model: 'anth',
  messages: [{ role: 'user', content: barleyPrompt }],
  temperature: 0.3,
  max_tokens: 1500
};

return [{ json: { topics, barleyRequestBody } }];

const ticket = $('Validate Ticket').first().json;
const barleyResponse = $input.first().json;

let enrichedDescription = ticket.description;

try {
  const choices = barleyResponse.choices || [];
  if (choices.length > 0 && choices[0].message && choices[0].message.content) {
    const barleyContext = choices[0].message.content;
    enrichedDescription = ticket.description + '\n\nAdditional Context from Barley:\n' + barleyContext;
  }
} catch (e) {
  // Barley failed or not configured, continue with original description
}

return [{ json: { enrichedDescription } }];

const ticket = $('Validate Ticket').first().json;
const { enrichedDescription } = $input.first().json;
const config = $('Set Config').first().json;

const systemPrompt = 'You are an expert Product Owner writing acceptance criteria for software development tickets.\n\nYour task is to analyze Jira tickets and generate clear, testable acceptance criteria.\n\nGUIDELINES:\n- Generate 3-7 acceptance criteria per ticket\n- Use the format that best fits each criterion:\n  - Given-When-Then for behavior-driven criteria\n  - Simple checkbox statements for state/condition criteria\n- Be SPECIFIC to THIS ticket - avoid generic criteria like "Code is tested" or "Documentation is updated"\n- Each criterion should be independently verifiable\n- If the description lacks sufficient detail to write meaningful ACs, set sufficient_information to false and explain why in skip_reason\n\nCONFIDENCE SCORING:\nAfter generating acceptance criteria, assign a confidence_score between 0.0 and 1.0 using the following scale:\n- 0.9-1.0: All requirements are clear and unambiguous, ACs are comprehensive\n- 0.7-0.89: Most requirements are clear, minor gaps exist\n- 0.5-0.69: Significant gaps in the description, several assumptions were made\n- Below 0.5: Major information is missing, ACs are largely speculative\n\nWhen confidence is below 0.9, list the specific gaps or questions in confidence_gaps. Each entry should describe a concrete area where information was lacking (e.g., "unclear user role", "missing error handling behavior", "no success/failure states defined"). When confidence is 0.9 or above, confidence_gaps should be empty.\n\nUse the submit_acceptance_criteria tool to provide your response.';

const userMessage = 'TICKET SUMMARY: ' + ticket.summary + '\n\nTICKET DESCRIPTION:\n' + (enrichedDescription || '(No description provided)') + '\n\nAnalyze this ticket and generate acceptance criteria using the submit_acceptance_criteria tool.';

const requestBody = {
  model: config.aiModel,
  max_tokens: parseInt(config.aiMaxTokens) || 1024,
  system: systemPrompt,
  tools: [{
    name: 'submit_acceptance_criteria',
    description: 'Submit the generated acceptance criteria for a Jira ticket',
    input_schema: {
      type: 'object',
      properties: {
        sufficient_information: {
          type: 'boolean',
          description: 'True if the ticket has enough information to generate meaningful acceptance criteria, False otherwise'
        },
        acceptance_criteria: {
          type: 'array',
          items: { type: 'string' },
          description: 'List of 3-7 clear, testable acceptance criteria. Empty if insufficient information.'
        },
        skip_reason: {
          type: 'string',
          description: 'Brief explanation of why ACs cannot be generated (only when sufficient_information is false)'
        },
        confidence_score: {
          type: 'number',
          description: 'A value between 0.0 and 1.0 representing confidence in the completeness and accuracy of the generated acceptance criteria.'
        },
        confidence_gaps: {
          type: 'array',
          items: { type: 'string' },
          description: 'Specific areas where the AI lacked information to produce fully confident acceptance criteria.'
        }
      },
      required: ['sufficient_information', 'acceptance_criteria', 'confidence_score', 'confidence_gaps']
    }
  }],
  tool_choice: { type: 'tool', name: 'submit_acceptance_criteria' },
  messages: [{ role: 'user', content: userMessage }]
};

return [{ json: { requestBody } }];

const config = $('Set Config').first().json;
const ticket = $('Validate Ticket').first().json;
const response = $input.first().json;

let acceptanceCriteria = [];
let confidenceScore = 0;
let confidenceGaps = [];
let sufficientInformation = false;

const content = response.content || [];
for (const block of content) {
  if (block.type === 'tool_use' && block.name === 'submit_acceptance_criteria') {
    sufficientInformation = block.input.sufficient_information || false;
    acceptanceCriteria = block.input.acceptance_criteria || [];
    confidenceScore = block.input.confidence_score || 0;
    confidenceGaps = block.input.confidence_gaps || [];
  }
}

const validAcs = acceptanceCriteria.filter(function(ac) {
  return typeof ac === 'string' && ac.trim().length > 0;
});
const hasValidAcs = sufficientInformation && validAcs.length > 0;

const threshold = parseFloat(config.confidenceThreshold) || 0.7;
const isLowConfidence = confidenceScore < threshold;
const needsEscalation = isLowConfidence && config.escalationEmail && config.escalationEmail.length > 0 && hasValidAcs;

let finalAcs = validAcs.slice();
if (isLowConfidence && hasValidAcs) {
  const note = 'Note: Clarification has been requested from the Product Owner. Please review the following draft acceptance criteria.';
  finalAcs = [note].concat(validAcs);
}

return [{ json: {
  hasValidAcs: hasValidAcs,
  acceptanceCriteria: finalAcs,
  confidenceScore: confidenceScore,
  confidenceGaps: confidenceGaps,
  needsEscalation: needsEscalation,
  ticketKey: ticket.ticketKey
} }];

const acsData = $('Parse & Prepare ACs').first().json;
const ticketResponse = $input.first().json;
const currentDescAdf = ticketResponse.fields ? ticketResponse.fields.description : null;

function generateLocalId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0;
    var v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const now = new Date();
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const month = months[now.getUTCMonth()];
const day = now.getUTCDate();
const year = now.getUTCFullYear();
const hours = now.getUTCHours();
const minutes = now.getUTCMinutes().toString().padStart(2, '0');
const ampm = hours >= 12 ? 'PM' : 'AM';
const hour12 = hours % 12 || 12;
const timestamp = month + ' ' + day + ', ' + year + ' at ' + hour12 + ':' + minutes + ' ' + ampm + ' UTC';

const taskItems = acsData.acceptanceCriteria.map(function(ac) {
  return {
    type: 'taskItem',
    attrs: { localId: generateLocalId(), state: 'TODO' },
    content: [{ type: 'text', text: ac }]
  };
});

const newAcContent = [
  {
    type: 'heading',
    attrs: { level: 2 },
    content: [{ type: 'text', text: 'Acceptance Criteria' }]
  },
  {
    type: 'taskList',
    attrs: { localId: generateLocalId() },
    content: taskItems
  },
  {
    type: 'paragraph',
    content: [{
      type: 'text',
      text: 'Generated by Jira AC Assistant (n8n) on ' + timestamp,
      marks: [{ type: 'em' }]
    }]
  }
];

var updatedDescription;
if (currentDescAdf && currentDescAdf.type === 'doc') {
  var existingContent = currentDescAdf.content || [];
  updatedDescription = {
    type: 'doc',
    version: 1,
    content: existingContent.concat(newAcContent)
  };
} else {
  updatedDescription = {
    type: 'doc',
    version: 1,
    content: newAcContent
  };
}

return [{ json: { updatedDescription: updatedDescription } }];
